package com.example;

import java.awt.Color;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("collisionmap")
public interface CollisionMapConfig extends Config
{
	@ConfigItem(
			keyName = "showBlockedTiles",
			name = "Show blocked tiles",
			description = "Highlight tiles that cannot be walked on"
	)
	default boolean showBlockedTiles()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showWalls",
			name = "Show walls",
			description = "Draw lines along cardinal movement boundaries (doesn't really work on its own since some walls adjacent to unwalkable tiles are ignored)"
	)
	default boolean showWalls()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "tileColor",
			name = "Tile color",
			description = "Color and transparency of blocked tiles"
	)
	default Color tileColor()
	{
		return new Color(255, 100, 0, 100);
	}

	@Alpha
	@ConfigItem(
			keyName = "wallColor",
			name = "Wall color",
			description = "Color and transparency of wall lines"
	)
	default Color wallColor()
	{
		return new Color(255, 100, 0, 100);
	}

	@Range(
			min = 1,
			max = 8
	)
	@ConfigItem(
			keyName = "wallThickness",
			name = "Wall thickness",
			description = "Thickness of collision wall lines"
	)
	default int wallThickness()
	{
		return 2;
	}
}

package com.example;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;

import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Perspective;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class CollisionMapOverlay extends Overlay
{

    private final Client client;
    private final CollisionMapConfig config;

    @Inject
    private CollisionMapOverlay(Client client, CollisionMapConfig config)
    {
        this.client = client;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        WorldView worldView = client.getTopLevelWorldView();

        if (worldView == null)
        {
            return null;
        }

        CollisionData[] collisionMaps = worldView.getCollisionMaps();

        if (collisionMaps == null)
        {
            return null;
        }

        int plane = worldView.getPlane();

        if (plane < 0 || plane >= collisionMaps.length
                || collisionMaps[plane] == null)
        {
            return null;
        }

        int[][] flags = collisionMaps[plane].getFlags();

        graphics.setStroke(new BasicStroke(
                config.wallThickness(),
                BasicStroke.CAP_BUTT,
                BasicStroke.JOIN_MITER
        ));

        for (int x = 0; x < flags.length; x++)
        {
            for (int y = 0; y < flags[x].length; y++)
            {
                int flag = flags[x][y];

                // Ignore tiles outside the usable scene
                if (flag == 0xFFFFFF)
                {
                    continue;
                }

                LocalPoint localPoint =
                        LocalPoint.fromScene(x, y, worldView);

                Polygon polygon =
                        Perspective.getCanvasTilePoly(client, localPoint);

                if (polygon == null)
                {
                    continue;
                }

                // Completely blocked tiles
                if (config.showBlockedTiles()
                        && (flag & CollisionDataFlag.BLOCK_MOVEMENT_FULL) != 0)
                {
                    graphics.setColor(config.tileColor());
                    graphics.fillPolygon(polygon);
                }

                // Cardinal walls
                if (config.showWalls()
                        && (flag & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0)
                {
                    graphics.setColor(config.wallColor());

                    // North
                    if ((flag & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) != 0
                            && y + 1 < flags[x].length
                            && (flags[x][y + 1] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0)
                    {
                        graphics.drawLine(
                                polygon.xpoints[2], polygon.ypoints[2],
                                polygon.xpoints[3], polygon.ypoints[3]
                        );
                    }

                    // East
                    if ((flag & CollisionDataFlag.BLOCK_MOVEMENT_EAST) != 0
                            && x + 1 < flags.length
                            && (flags[x + 1][y] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0)
                    {
                        graphics.drawLine(
                                polygon.xpoints[1], polygon.ypoints[1],
                                polygon.xpoints[2], polygon.ypoints[2]
                        );
                    }

                    // South
                    if ((flag & CollisionDataFlag.BLOCK_MOVEMENT_SOUTH) != 0
                            && y - 1 >= 0
                            && (flags[x][y - 1] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0)
                    {
                        graphics.drawLine(
                                polygon.xpoints[0], polygon.ypoints[0],
                                polygon.xpoints[1], polygon.ypoints[1]
                        );
                    }

                    // West
                    if ((flag & CollisionDataFlag.BLOCK_MOVEMENT_WEST) != 0
                            && x - 1 >= 0
                            && (flags[x - 1][y] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0)
                    {
                        graphics.drawLine(
                                polygon.xpoints[3], polygon.ypoints[3],
                                polygon.xpoints[0], polygon.ypoints[0]
                        );
                    }
                }
            }
        }

        return null;
    }
}

package com.example;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
		name = "Collision Map"
)
public class CollisionMapPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CollisionMapOverlay collisionMapOverlay;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(collisionMapOverlay);
		log.info("Collision Map started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(collisionMapOverlay);
		log.info("Collision Map stopped!");
	}

	@Provides
	CollisionMapConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CollisionMapConfig.class);
	}
}

package com.example;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CollisionMapPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CollisionMapPlugin.class);
		RuneLite.main(args);
	}
}
